package com.franco.desco.adapter.in.web.campaignparticipant;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.campaignparticipant.*;import com.franco.desco.application.campaignparticipant.port.in.CampaignParticipantUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/participantes-campania")@Tag(name="Participantes de campaña",description="Inclusión, consulta, programación y retiro de socios de campaña.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class CampaignParticipantController{private final CampaignParticipantUseCase u;private final CampaignParticipantWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CampaignParticipantController(CampaignParticipantUseCase u,CampaignParticipantWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'PARTICIPANTES_LISTAR')")@Operation(operationId="participantesListar",summary="Listar participantes")public ResponseEntity<ApiResponse<PageResponse<CampaignParticipantResponses.Summary>>>list(@RequestParam(required=false)Long campaniaVentaId,@RequestParam(required=false)String estadoParticipacion,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,campaniaVentaId,estadoParticipacion),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'PARTICIPANTES_VER')")@Operation(operationId="participantesVer",summary="Ver participante")public ResponseEntity<ApiResponse<CampaignParticipantResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new CampaignParticipantCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PARTICIPANTES_CREAR')")@Operation(operationId="participantesIncluir",summary="Incluir socio en campaña")public ResponseEntity<ApiResponse<CampaignParticipantResponses.Created>>include(@Valid@RequestBody CampaignParticipantRequests.Include q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.include(new CampaignParticipantCommands.Include(q.campaniaVentaId(),q.socioAsociacionId()),ids.resolve(a),meta.resolve(r)),r,CampaignParticipantResponses.Created::new);}
 @PostMapping("/{id}/programar-operativo")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PARTICIPANTES_CREAR')")@Operation(operationId="participantesProgramarOperativo",summary="Programar socio en operativo")public ResponseEntity<ApiResponse<CampaignParticipantResponses.Created>>program(@PathVariable Long id,@Valid@RequestBody CampaignParticipantRequests.Program q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.program(new CampaignParticipantCommands.Program(id,q.operativoVentaId()),ids.resolve(a),meta.resolve(r)),r,CampaignParticipantResponses.Created::new);}
 @PostMapping("/{id}/retirar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PARTICIPANTES_RETIRAR')")@Operation(operationId="participantesRetirar",summary="Retirar socio de campaña")public ResponseEntity<ApiResponse<Void>>remove(@PathVariable Long id,@Valid@RequestBody CampaignParticipantRequests.Remove q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.remove(new CampaignParticipantCommands.Remove(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
